"use strict";(self.webpackChunknotes_by_sara=self.webpackChunknotes_by_sara||[]).push([["86581"],{90914(e){e.exports=JSON.parse('{"id":"FIN-838","slug":"contactless-payment","term":"Contactless Payment","also_known_as":[],"difficulty":"Beginner","definition":"Contactless payment is a way of paying by tapping a card, phone, smartwatch or other device on a payment terminal, without inserting a card or, for smaller amounts, entering a PIN.","explanation":["Contactless payments use short-range wireless technology, typically near-field communication, to transmit payment information securely between the card or device and the terminal.","Contactless cards are standard in many countries. Mobile wallets, such as Apple Pay, Google Pay and Samsung Pay, store card details on a phone or smartwatch and allow the same tap-to-pay convenience.","For example, a customer buying a coffee can simply tap their card or phone on the reader, and the payment is completed within a second or two.","Contactless payments are faster and more convenient than inserting a card or using cash. Security features include encryption and tokenization, which replace the real card number with a unique code for each transaction, so the card details are not exposed. Many countries set a maximum amount for contactless card payments without a PIN, and after several contactless transactions in a row, the customer may be asked to enter their PIN to confirm their identity. Mobile wallet payments often use the phone\'s fingerprint or face recognition instead, allowing higher limits."],"note":"","total":1500,"prev":{"slug":"consumer-surplus","term":"Consumer Surplus"},"next":{"slug":"contango","term":"Contango"}}')}}]);